#pragma once
#include "../Runtime/HostedClientState.h"

namespace coincide {
template<class Check,class Reject>void hosted_owner_resolution_checks(const std::filesystem::path& parent,const Check& check,const Reject& rejects){
    using namespace background_host;using Op=HostedIntentOperation;using D=HostedIntentDisposition;const auto root=parent/L"owner-reviewed-inputs";std::filesystem::create_directory(root);auto scope=std::make_shared<Scope>(root);HostedClientState store(scope);store.open();Key key{new_guid(),"codex"};HostedClientBinding binding{new_guid(),std::string(64,'a'),"default",{}};const auto proof=[&](std::uint64_t seq){return AgentPersistReceipt{{binding.epoch,seq},true,true};};store.begin_generation(key,binding,{proof(0),true});const auto direct=new_guid(),queued=new_guid(),steered=new_guid();store.prepare_intent(key,direct,Op::send);check(store.locally_prepared(key,direct,Op::send)&&!store.locally_prepared(key,direct,Op::queue),"Fresh local preparation must bind its exact input operation");store.record_host_status(key,direct,"unknown");check(!store.locally_prepared(key,direct,Op::send),"Uncertain status must remove current-instance non-dispatch proof");store.prepare_intent(key,queued,Op::queue);store.record_host_status(key,queued,"accepted");store.prepare_intent(key,steered,Op::steer);store.record_host_status(key,steered,"unknown");SessionInfo host{key,binding.epoch,false,false,true,5,0,{}};host.profile_id=binding.profile_id;host.launch_fingerprint=binding.launch_fingerprint;host.queue_paused=true;const auto event=[&](const std::string& id,bool saved,std::uint64_t seq){return SessionEvent{SessionEvent::Kind::queue_changed,id,std::string(saved?stopped_queue_resolution_text:stopped_input_resolution_text),std::string(saved?stopped_queue_resolution_detail:stopped_input_resolution_detail),AgentEventReceipt{binding.epoch,seq,id}};};const auto admin=event(direct,false,5);
    auto wrong=host;wrong.live=true;rejects([&]{store.observe_owner_resolution(key,admin,wrong);},"Live status cannot prove owner-reviewed stopped recovery");wrong=host;wrong.busy=true;rejects([&]{store.observe_owner_resolution(key,admin,wrong);},"Busy stopped work cannot be resolved from an in-flight status");wrong=host;wrong.snapshots_included=false;rejects([&]{store.observe_owner_resolution(key,admin,wrong);},"A lightweight summary cannot prove administrative recovery");wrong=host;wrong.launch_fingerprint=std::string(64,'b');rejects([&]{store.observe_owner_resolution(key,admin,wrong);},"Owner resolution must bind the exact original launch fingerprint");wrong=host;wrong.profile_id=new_guid().substr(1,36);rejects([&]{store.observe_owner_resolution(key,admin,wrong);},"Owner resolution must bind the original profile");wrong=host;wrong.epoch=new_guid();rejects([&]{store.observe_owner_resolution(key,admin,wrong);},"Owner resolution must bind the exact original epoch");wrong=host;wrong.last=4;rejects([&]{store.observe_owner_resolution(key,admin,wrong);},"Full host status must cover the actual resolution receipt prefix");wrong=host;wrong.queued={{direct,CodexTurn{}}};wrong.queued_count=1;rejects([&]{store.observe_owner_resolution(key,admin,wrong);},"Owner resolution cannot ignore a still-saved target");auto bad=admin;bad.text="not delivered";rejects([&]{store.observe_owner_resolution(key,bad,host);},"Administrative proof must preserve the exact disclosure rather than assert non-delivery");bad=admin;bad.receipt->delivery_id=new_guid();rejects([&]{store.observe_owner_resolution(key,bad,host);},"Administrative receipt must preserve the exact stable local input ID");rejects([&]{store.observe_owner_resolution(key,event(direct,true,5),host);},"A queue-cancellation receipt cannot resolve a direct input");rejects([&]{store.observe_owner_resolution(key,event(new_guid(),false,5),host);},"Owner recovery cannot invent an original durable input intent");
    check(store.observe_owner_resolution(key,admin,host),"An explicit original stopped direct input may receive separate administrative proof even before account verification");const auto observed=store.get(key)->pending.front();check(observed.disposition==D::uncertain&&observed.owner_resolution->sequence==5&&!observed.delivered&&!observed.settled&&store.get(key)->binding.account_scope.empty(),"Owner-reviewed recovery must preserve uncertainty without inventing account/delivery/model evidence");check(!store.observe_owner_resolution(key,admin,host),"Reapplying the identical durable admin receipt must be idempotent");host.last=6;rejects([&]{store.observe_owner_resolution(key,event(direct,false,6),host);},"A different admin receipt cannot silently replace the original proof");rejects([&]{store.retire_not_delivered(key,direct,proof(5));},"Administrative resolution must never masquerade as not-delivered retirement");rejects([&]{store.retire_owner_resolution(key,direct,proof(4));},"Owner resolution cannot retire before its exact saved prefix");auto partial=proof(5);partial.index_durable=false;rejects([&]{store.retire_owner_resolution(key,direct,partial);},"Owner recovery requires actual transcript and index persistence");auto foreign=proof(5);foreign.cursor.epoch=new_guid();rejects([&]{store.retire_owner_resolution(key,direct,foreign);},"Another epoch's saved prefix cannot retire owner recovery");
    HostedClientState reopened(scope);check(reopened.open().front().pending.front().owner_resolution->sequence==5&&reopened.get(key)->pending.front().disposition==D::uncertain&&reopened.reconcile_ids(key).size()==2,"Crash restore must preserve owner proof and original uncertainty without replaying or resubmitting its input");check(reopened.retire_owner_resolution(key,direct,proof(5)),"Only actual durable original-input/admin-prefix preservation may retire owner-resolved metadata");host.account_scope=std::string(64,'c');const auto queue_admin=event(queued,true,6);check(reopened.observe_owner_resolution(key,queue_admin,host)&&reopened.get(key)->pending.front().disposition==D::accepted&&reopened.get(key)->binding.account_scope==host.account_scope,"Queue admin proof may bind only authenticated original identity and preserves earlier accepted status");rejects([&]{reopened.record_queue_removal(key,queued,true);},"Future saved-work cancellation cannot be reinterpreted as live removal/non-delivery proof");check(reopened.retire_owner_resolution(key,queued,proof(6)),"A future saved-work cancellation may retire only after its own receipt prefix is durable");host.last=7;wrong=host;wrong.account_scope=std::string(64,'d');rejects([&]{reopened.observe_owner_resolution(key,event(steered,false,7),wrong);},"The same original generation cannot switch its verified account during recovery");check(reopened.observe_owner_resolution(key,event(steered,false,7),host)&&reopened.get(key)->pending.front().disposition==D::uncertain,"A stopped uncertain steering input may be administratively resolved without claiming model absence");check(reopened.retire_owner_resolution(key,steered,proof(7))&&reopened.get(key)->pending.empty(),"Explicit durable owner recovery can clear original unresolved IDs without any resubmission");host.acknowledged=7;rejects([&]{reopened.retire_generation(key,host,proof(7));},"Resolving pending inputs must preserve the separate original host review gate");host.review=false;check(reopened.retire_generation(key,host,proof(7)),"Only explicit reviewed fully persisted/ACKed stopped state may finally retire its generation");
}
} // namespace coincide
